package financeos.cloud;
import financeos.vk.*;import com.fasterxml.jackson.databind.*;import com.sun.net.httpserver.*;import java.net.*;import java.net.http.*;import java.time.*;import java.util.*;import java.nio.charset.StandardCharsets;
public final class StorageRetentionTest {
 public static void main(String[]a)throws Exception{
  var now=Instant.parse("2026-11-13T12:00:00Z");var items=new ArrayList<StorageRetention.Item>();var prefix="java-v1/restore-points/";
  for(int i=0;i<22;i++)items.add(new StorageRetention.Item(prefix+"events/"+String.format("20261113T1200%02d000",i)+"-"+"a".repeat(64)+".json","v"+i,true,10,now));
  var deletes=StorageRetention.eventDeletes(items);if(deletes.size()!=2||!deletes.getFirst().version().equals("v1")||!deletes.getLast().version().equals("v0"))throw new AssertionError("Latest 20 not protected");
  items.add(new StorageRetention.Item("java-v1/state.json","current",true,50,now));items.add(new StorageRetention.Item("java-v1/state.json","old",false,50,now));items.add(new StorageRetention.Item("java-v1/base.json","original",false,50,now));
  items.add(new StorageRetention.Item(prefix+"daily/2026-10-14.json","expired",true,10,now));items.add(new StorageRetention.Item(prefix+"daily/2026-10-15.json","boundary",true,10,now));items.add(new StorageRetention.Item(prefix+"daily/2026-11-13.json","today",true,10,now));
  var pending=new VkEvent("message_new",99,42,2000000001L,"pending","",99);String pendingHash=CloudVkIngress.eventId(pending);var replies=new LinkedHashMap<String,CloudVkProcessor.SavedReply>();replies.put(pendingHash,new CloudVkProcessor.SavedReply("saved",financeos.core.Screen.MAIN,null,null,pending,false));var env=new CloudVkProcessor.Envelope(1,"",replies,new LinkedHashSet<>(),"",100);
  var mapper=new ObjectMapper();var payloads=new HashMap<String,byte[]>();for(var pair:List.of(new VkEvent("message_new",99,42,2000000001L,"processed","",90),pending,new VkEvent("message_new",99,42,2000000001L,"unprocessed","",101))){String key="inbox/"+CloudVkIngress.eventId(pair)+".json";items.add(new StorageRetention.Item(key,"evt-"+pair.eventId(),true,10,now.minus(Duration.ofDays(8))));payloads.put(key,mapper.writeValueAsBytes(pair));}
  var deleted=new HashSet<String>();var server=HttpServer.create(new InetSocketAddress(InetAddress.getLoopbackAddress(),0),0);server.createContext("/test-bucket/",exchange->{try{String path=exchange.getRequestURI().getPath().substring("/test-bucket/".length());if(exchange.getRequestMethod().equals("DELETE")){String version=URLDecoder.decode(exchange.getRequestURI().getRawQuery().substring("versionId=".length()),StandardCharsets.UTF_8);if(!Set.of("v0","v1","expired","evt-processed").contains(version))throw new AssertionError("Protected object deleted "+version);deleted.add(version);exchange.sendResponseHeaders(204,-1);return;}
    byte[] body;if(path.isEmpty()){var s=new StringBuilder("<ListVersionsResult xmlns='http://s3.amazonaws.com/doc/2006-03-01'><IsTruncated>false</IsTruncated>");for(var i:items)s.append("<Version><Key>").append(i.key()).append("</Key><VersionId>").append(i.version()).append("</VersionId><IsLatest>").append(i.latest()).append("</IsLatest><Size>").append(i.size()).append("</Size><LastModified>").append(i.modified()).append("</LastModified></Version>");body=s.append("</ListVersionsResult>").toString().getBytes(StandardCharsets.UTF_8);}else body=payloads.get(path);exchange.sendResponseHeaders(200,body.length);exchange.getResponseBody().write(body);
   }catch(Throwable failure){failure.printStackTrace();exchange.sendResponseHeaders(500,-1);}finally{exchange.close();}});server.start();try{var retention=new StorageRetention(HttpClient.newHttpClient(),URI.create("http://127.0.0.1:"+server.getAddress().getPort()),"test-bucket",()->"dummy","java-v1/state.json");var result=retention.maintain(env,99,2000000001L,now);if(result.incomplete()||result.removed()!=4||deleted.size()!=4)throw new AssertionError("Retention failed "+result);}
  finally{server.stop(0);}
  System.out.println("Retention: latest 20, 30-day daily boundary, exact version deletion, original/current/pending/unprocessed protections passed.");
 }
}
